declare(strict_types=1);
use function DBLESSCMS\e;
$data=$page['content'];
?>
<?php if ($page['page']==='home'): require $store->templates->path($id,'pages',$manifest['pages']['home']); ?>
<?php elseif ($page['page']==='404'): ?>
<section class="section not-found"><div class="container text-flow"><p class="error-number" aria-hidden="true">404</p><h1><?= e('Página não encontrada') ?></h1><p class="lead"><?= e($data['lead']!==''?$data['lead']:'O endereço solicitado não está disponível. A navegação pode continuar pela página inicial.') ?></p><a class="button" href="<?= e($base_url.'/') ?>"><?= e('Voltar ao início') ?></a></div></section>
<?php else: require $store->templates->path($id,'partials',$manifest['partials']['breadcrumbs']); ?>
