<section class="section detail-body"><div class="container detail-grid"><div class="article-content text-flow"><p class="article-summary"><?= e($data['summary']) ?></p><?php foreach ($data['sections'] as $section): ?><section><?php if($section['title']!==''): ?><h2><?= e($section['title']) ?></h2><?php endif; ?><?php foreach ($section['body']??[] as $paragraph): echo $components->paragraph($paragraph);endforeach; ?><?php if (!empty($section['list'])): ?><ul><?php foreach ($section['list'] as $entry): ?><li><?= e($entry) ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endforeach; ?><?php require $store->templates->path($id,'partials',$manifest['partials']['slide-blocks']); ?><?php if($data['demonstrateMenus']??false)require $store->templates->path($id,'partials',$manifest['partials']['menu-examples']); ?></div><aside class="detail-aside"><?php if ($data['facts']!==[]): ?><div class="facts-card"><h2><?= e('Detalhes') ?></h2><dl><?php foreach ($data['facts'] as $fact): ?><div><dt><?= e($fact['label']) ?></dt><dd><?= e($fact['value']) ?></dd></div><?php endforeach; ?></dl></div><?php endif; ?><?php if ($data['related']!==[]): ?><nav class="related-links" aria-label="<?= e('Explore também') ?>"><h2><?= e('Explore também') ?></h2><?php foreach ($data['related'] as $related): ?><a href="<?= e($pageUrl($related['href'])) ?>"><?= e($related['label']) ?> <span aria-hidden="true">↗</span></a><?php endforeach; ?></nav><?php endif; ?></aside></div></section>
